head.b:skin:
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-page: #fafafa;
  --bg-card: #ffffff;
  --bg-subtle: #f5f5f5;
  --text-primary: #171717;
  --text-secondary: #525252;
  --text-muted: #737373;
  --border-color: #e5e5e5;
  --accent: #d97706;
  --accent-soft: #fef3c7;
  --accent-text: #92400e;
  --primary: #0a0a0a;
  --primary-contrast: #ffffff;
  --whatsapp: #059669;
  --rose: #e11d48;
  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-serif: 'Source Serif 4', Georgia, serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06);
}

body.dark-mode {
  --bg-page: #0a0a0a;
  --bg-card: #141414;
  --bg-subtle: #1c1c1c;
  --text-primary: #f5f5f5;
  --text-secondary: #a3a3a3;
  --text-muted: #737373;
  --border-color: #262626;
  --accent-soft: rgba(217, 119, 6, 0.16);
  --accent-text: #fde68a;
  --primary: #ffffff;
  --primary-contrast: #0a0a0a;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-page);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  transition: background-color 0.2s ease, color 0.2s ease;
}

/* Hide legacy preloaders, Blogger navbar, attribution, post images, and ad clutter */
#loader, .preloader, #outline, .check-out,
#navbar-iframe, .navbar-iframe, .Attribution,
.post-body img, .post-body picture, .post-body figure,
.post-body .separator, .post-body .tr-caption-container,
.post-body ins, .post-body iframe,
.adsbygoogle, ins.adsbygoogle, iframe[src*="ad"],
[id*="ad-"], [class*="ad-banner"], [class*="ad-slot"] {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.15s ease, border-color 0.15s ease, background-color 0.15s ease;
}

button, input, select, textarea {
  font-family: inherit;
}

.container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 16px;
}

/* Top Announcement Bar */
.top-bar {
  background-color: #050505;
  color: #a3a3a3;
  font-size: 11px;
  padding: 7px 16px;
  border-bottom: 1px solid #262626;
  text-align: center;
}
.top-bar strong { color: #f5f5f5; }
.top-bar a { color: #fbbf24; font-weight: 600; }
.top-bar a:hover { text-decoration: underline; }

/* Sticky Navbar */
.navbar-wrapper {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border-color);
}
body.dark-mode .navbar-wrapper {
  background: rgba(20, 20, 20, 0.94);
}
.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
  gap: 12px;
}
.brand-group {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.brand-monogram {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--primary);
  color: var(--primary-contrast);
  font-size: 17px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid var(--border-color);
}
.brand-title {
  font-size: 17px;
  font-weight: 800;
  letter-spacing: -0.4px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.badge-tag {
  font-size: 9px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--accent-soft);
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.brand-sub {
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.nav-links {
  display: none;
  align-items: center;
  gap: 18px;
  list-style: none;
}
@media (min-width: 960px) {
  .nav-links { display: flex; }
}
.nav-link {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
}
.nav-link:hover { color: var(--text-primary); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.btn-wa-header {
  background: var(--whatsapp);
  color: #ffffff;
  padding: 8px 13px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
  display: none;
  align-items: center;
  gap: 6px;
}
@media (min-width: 640px) {
  .btn-wa-header { display: inline-flex; }
}
.btn-icon {
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 7px 11px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}
.btn-icon:hover {
  background: var(--bg-subtle);
}
.mobile-menu-btn {
  display: inline-flex;
}
@media (min-width: 960px) {
  .mobile-menu-btn { display: none; }
}
.mobile-drawer {
  display: none;
  border-top: 1px solid var(--border-color);
  background: var(--bg-card);
  padding: 12px 16px 16px;
}
.mobile-drawer.open { display: block; }
.mobile-drawer a {
  display: block;
  padding: 10px 8px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
}
.mobile-drawer a:last-child { border-bottom: none; }

/* Hero Section */
.hero-section {
  padding: 44px 0 48px;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-card);
}
.hero-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 32px;
}
@media (min-width: 960px) {
  .hero-grid {
    grid-template-columns: 7fr 5fr;
    align-items: center;
  }
}
.hero-kicker {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--accent);
  letter-spacing: 0.5px;
  margin-bottom: 14px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.hero-kicker .verified-link {
  color: var(--whatsapp);
}
.author-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
}
.author-monogram {
  width: 44px;
  height: 44px;
  border-radius: 11px;
  background: var(--primary);
  color: var(--primary-contrast);
  font-weight: 800;
  font-size: 17px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  flex-shrink: 0;
}
.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #10b981;
  border: 2px solid var(--bg-card);
  position: absolute;
  bottom: -2px;
  right: -2px;
}
.hero-title {
  font-size: 30px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.6px;
  margin-bottom: 14px;
}
@media (min-width: 640px) {
  .hero-title { font-size: 42px; }
}
.hero-desc {
  font-size: 15px;
  color: var(--text-secondary);
  margin-bottom: 20px;
  line-height: 1.65;
}
.hero-quote {
  background: var(--bg-page);
  border: 1px solid var(--border-color);
  border-left: 4px solid var(--accent);
  padding: 15px 16px;
  border-radius: 10px;
  font-style: italic;
  font-family: var(--font-serif);
  margin-bottom: 22px;
  color: var(--text-primary);
  font-size: 15px;
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 24px;
}
.btn-primary {
  background: var(--primary);
  color: var(--primary-contrast);
  padding: 11px 18px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: none;
  cursor: pointer;
}
.btn-outline {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 11px 18px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
}
.btn-outline:hover {
  background: var(--bg-subtle);
}

.metrics-bar {
  padding-top: 18px;
  border-top: 1px solid var(--border-color);
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 14px;
}
@media (min-width: 640px) {
  .metrics-bar { grid-template-columns: repeat(4, 1fr); }
}
.metric-val { font-size: 15px; font-weight: 800; }
.metric-lbl { font-size: 11px; color: var(--text-muted); }

/* Pillars Stack */
.pillars-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.pillar-card {
  display: block;
  background: var(--bg-page);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 16px;
}
.pillar-card:hover {
  border-color: var(--text-muted);
}
.pillar-title {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 4px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.pillar-desc {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* Main Sections */
.section-pad {
  padding: 48px 0;
  border-bottom: 1px solid var(--border-color);
}
.sec-tag {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--accent);
  letter-spacing: 0.5px;
  margin-bottom: 8px;
}
.sec-title {
  font-size: 26px;
  font-weight: 800;
  margin-bottom: 8px;
  letter-spacing: -0.4px;
}
.sec-desc {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 28px;
  max-width: 680px;
}

/* Grids */
.grid-2 {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}
@media (min-width: 768px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
}
.grid-3 {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}
@media (min-width: 768px) {
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 1024px) {
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
}

.content-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 14px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: var(--shadow-sm);
}
.card-accent-line {
  height: 3px;
  width: 48px;
  background: var(--accent);
  border-radius: 99px;
  margin-bottom: 14px;
}
.content-card h3 {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 8px;
  line-height: 1.35;
}
.content-card p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
}

/* Blog Posts Feed & Filter */
.feed-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 24px;
}
.search-input {
  width: 100%;
  max-width: 320px;
  padding: 9px 12px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: var(--bg-page);
  color: var(--text-primary);
  font-size: 13px;
}
.post-card {
  background: var(--bg-page);
  border: 1px solid var(--border-color);
  border-radius: 14px;
  padding: 24px;
  margin-bottom: 20px;
  box-shadow: var(--shadow-sm);
}
.post-meta {
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 12px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}
.post-title {
  font-size: 22px;
  font-weight: 800;
  line-height: 1.3;
  margin-bottom: 8px;
  letter-spacing: -0.3px;
}
.post-title a:hover { color: var(--accent); }
.post-body {
  font-family: var(--font-serif);
  font-size: 16px;
  line-height: 1.75;
  color: var(--text-primary);
}
.post-body h2, .post-body h3, .post-body h4 {
  font-family: var(--font-sans);
  margin: 22px 0 10px;
  font-weight: 700;
}
.post-body p { margin-bottom: 14px; }
.post-body ul, .post-body ol { margin-left: 20px; margin-bottom: 14px; }
.post-body li { margin-bottom: 6px; }
.post-body a { color: var(--accent); text-decoration: underline; }

.pager-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 24px;
}

/* Student Calculator */
.calc-box {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 26px;
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}
@media (min-width: 860px) {
  .calc-box { grid-template-columns: 1fr 1fr; align-items: center; }
}
.calc-input-group { margin-bottom: 16px; }
.calc-label {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 8px;
  display: block;
  color: var(--text-muted);
}
.calc-select {
  width: 100%;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: var(--bg-page);
  color: var(--text-primary);
  font-size: 13px;
}
.calc-result-box {
  background: var(--accent-soft);
  border: 1px solid rgba(217, 119, 6, 0.25);
  border-radius: 12px;
  padding: 22px;
  color: var(--accent-text);
}
.calc-amount {
  font-size: 36px;
  font-weight: 800;
  margin: 6px 0;
}

/* Charity Highlight */
.charity-band {
  background: #0a0a0a;
  color: #f5f5f5;
  padding: 52px 0;
  text-align: center;
  border-bottom: 1px solid #262626;
}
.charity-quote {
  font-family: var(--font-serif);
  font-style: italic;
  color: #fda4af;
  font-size: 18px;
  margin: 10px 0 14px;
}

/* Contact Cards */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}
@media (min-width: 860px) {
  .contact-grid { grid-template-columns: 5fr 7fr; }
}
.contact-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 15px 16px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  margin-bottom: 12px;
}
.contact-item:hover {
  border-color: var(--text-muted);
}
.contact-icon {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background: var(--bg-page);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 800;
  border: 1px solid var(--border-color);
  flex-shrink: 0;
}
.form-input {
  width: 100%;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: var(--bg-page);
  color: var(--text-primary);
  font-size: 13px;
}

/* Footer */
footer {
  background: #050505;
  color: #a3a3a3;
  padding: 48px 0 24px;
  font-size: 12px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 32px;
  margin-bottom: 36px;
}
@media (min-width: 768px) {
  .footer-grid { grid-template-columns: 2fr 1fr 1fr 1fr; }
}
.footer-col h4 {
  color: #f5f5f5;
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 8px; }
.footer-col a:hover { color: #ffffff; }
.footer-btm {
  border-top: 1px solid #262626;
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  color: #737373;
}

body.script:
//
(function() {
  // 1. Theme persistence
  try {
    var savedTheme = localStorage.getItem('mrs_theme');
    if (savedTheme === 'dark') {
      document.body.classList.add('dark-mode');
    }
  } catch (e) {}

  var themeBtn = document.getElementById('theme-toggle-btn');
  if (themeBtn) {
    themeBtn.addEventListener('click', function() {
      document.body.classList.toggle('dark-mode');
      try {
        localStorage.setItem('mrs_theme', document.body.classList.contains('dark-mode') ? 'dark' : 'light');
      } catch (e) {}
    });
  }

  // 2. Mobile drawer toggle
  var menuBtn = document.getElementById('mobile-menu-btn');
  var drawer = document.getElementById('mobile-drawer');
  if (menuBtn && drawer) {
    menuBtn.addEventListener('click', function() {
      drawer.classList.toggle('open');
    });
    var drawerLinks = drawer.querySelectorAll('a');
    for (var i = 0; i < drawerLinks.length; i++) {
      drawerLinks[i].addEventListener('click', function() {
        drawer.classList.remove('open');
      });
    }
  }

  // 3. Strip legacy post images, ad scripts, iframes, and ad/monetization links from Blogger post bodies
  var adPattern = /(profitableratecpm|uplcm|adsterra|effectiveratecpm|highperformanceformat|popads|propellerads|googlesyndication|doubleclick|monetag|onclick|hilltopads|clickadu|exoclick|juicyads|revenuehits|mgid|taboola|outbrain|adroll|adnxs|shrinkme|ouo\.io|adf\.ly)/i;
  var bodies = document.querySelectorAll('.post-body');
  for (var b = 0; b < bodies.length; b++) {
    var bodyEl = bodies[b];
    var mediaAndAds = bodyEl.querySelectorAll('img, picture, figure, .separator, ins, iframe, script');
    for (var m = 0; m < mediaAndAds.length; m++) {
      if (mediaAndAds[m].parentNode) {
        mediaAndAds[m].parentNode.removeChild(mediaAndAds[m]);
      }
    }
    var links = bodyEl.querySelectorAll('a[href]');
    for (var l = 0; l < links.length; l++) {
      var href = links[l].getAttribute('href') || '';
      if (adPattern.test(href) && links[l].parentNode) {
        links[l].parentNode.removeChild(links[l]);
      }
    }
  }

  // 4. Live post keyword filter
  var filterInput = document.getElementById('post-filter-input');
  if (filterInput) {
    filterInput.addEventListener('input', function() {
      var query = (filterInput.value || '').toLowerCase().trim();
      var cards = document.querySelectorAll('#post-section .post-card');
      for (var c = 0; c < cards.length; c++) {
        var txt = (cards[c].innerText || cards[c].textContent || '').toLowerCase();
        cards[c].style.display = (!query || txt.indexOf(query) !== -1) ? 'block' : 'none';
      }
    });
  }

  // 5. Student Weekly Time Planner
  var slider = document.getElementById('hours-slider');
  var skillSelect = document.getElementById('skill-select');
  function updateCalc() {
    if (!slider || !skillSelect) return;
    var hours = parseInt(slider.value, 10) || 10;
    var tools = skillSelect.value || 'Google Docs / LibreOffice';
    var hoursEl = document.getElementById('hours-val');
    var totalEl = document.getElementById('calc-total');
    var toolsEl = document.getElementById('calc-tools');
    if (hoursEl) hoursEl.textContent = String(hours);
    if (totalEl) totalEl.textContent = (hours * 4) + ' hrs / mo';
    if (toolsEl) toolsEl.textContent = 'Free Tools: ' + tools + ' · Zero upfront cost required.';
  }
  if (slider) slider.addEventListener('input', updateCalc);
  if (skillSelect) skillSelect.addEventListener('change', updateCalc);
  updateCalc();

  // 6. Direct Contact Form
  var contactForm = document.getElementById('direct-contact-form');
  if (contactForm) {
    contactForm.addEventListener('submit', function(e) {
      e.preventDefault();
      var name = (document.getElementById('msg-name') || {}).value || '';
      var email = (document.getElementById('msg-email') || {}).value || '';
      var msg = (document.getElementById('msg-text') || {}).value || '';
      var payload = 'Hello M R S, my name is ' + name + (email ? ' (' + email + ')' : '') + '. Message: ' + msg;
      window.open('https://wa.me/8809611056361?text=' + encodeURIComponent(payload), '_blank', 'noopener,noreferrer');
    });
  }
})();
//
